"""Rebuild the single compiler course page from the original chapter notes."""

from pathlib import Path
import re


ROOT = Path(__file__).resolve().parents[1]
CHAPTERS = ROOT / "docs" / "exam" / "compiler"
OUTPUT = ROOT / "docs" / "exam" / "compiler.md"


def combine() -> str:
    sources = sorted(CHAPTERS.glob("[0-9][0-9]-*.md"))
    expected = [f"{number:02}" for number in range(14)] + ["99"]
    if [source.name[:2] for source in sources] != expected:
        raise ValueError(f"Expected chapters 00-13 and 99 in {CHAPTERS}")

    parts = [
        "<!-- Generated by scripts/combine_compiler.py; edit the original chapters. -->\n"
        "# 编译原理速通笔记\n\n"
        '<div class="chapter-shortcuts" markdown>\n\n'
        "[学习路线](#chapter-00){ .md-button }\n"
        "[词法分析](#chapter-02){ .md-button }\n"
        "[语法分析](#chapter-03){ .md-button }\n"
        "[考前总复习](#chapter-99){ .md-button }\n\n"
        "</div>"
    ]
    for source in sources:
        lines = []
        fence = None
        for line in source.read_text(encoding="utf-8").splitlines():
            marker = re.match(r"^\s*(`{3,}|~{3,})", line)
            if marker:
                token = marker.group(1)
                if fence is None:
                    fence = token
                elif token[0] == fence[0] and len(token) >= len(fence):
                    fence = None
            elif fence is None:
                heading = re.match(r"^(#{1,6}) (.+)$", line)
                if heading:
                    level = len(heading.group(1))
                    line = "#" * min(level + 1, 6) + " " + heading.group(2)
                    if level == 1:
                        line += f" {{#chapter-{source.name[:2]}}}"
            lines.append(line)
        parts.append("\n".join(lines).strip())
    return "\n\n---\n\n".join(parts) + "\n"


if __name__ == "__main__":
    OUTPUT.write_text(combine(), encoding="utf-8")
    print(f"Updated {OUTPUT.name} with 15 chapters")
